mapper.select:
/* statusCodeList */
SELECT DISTINCT product_state
from tb_product_detail

/* kr.happyjob.study.vo.requests.HistoryModel */
SELECT
    U.team AS team,
    U.name AS name,
    P.product_name AS productName,
    PD.rental_date AS rentalDate,
    PD.return_date AS returnDate,
    PD.product_detail_code AS productDetailCode,
    PD.product_no AS productNo,
    PD.product_state AS status,
    CC.category_name
FROM tb_product_detail PD
INNER JOIN tb_product_info P ON PD.product_no = P.product_no
INNER JOIN tb_userinfo U ON PD.loginID = U.loginID
INNER JOIN tb_category_code as CC ON PD.category_code = CC.category_code

    /* 괄호를 통해 해당 평가가 먼저 되게 함, () -> NOT-> AND -> OR 순으로 평가됨*/
    (PD.rental_date IS NOT NULL OR PD.return_date IS NOT NULL)

        /* 컨트롤러에서 이 값을 넣으면 일반유저, 없으면 관리자*/
        AND PD.loginID = #{loginID}

    /* 관리자 */



                /* TEAM */


                        AND U.team LIKE CONCAT('%',#{searchSubSel},'%')


                        AND U.team IS NULL


                /* NAME */


                        AND U.name LIKE CONCAT('%',#{searchSubSel},'%')


                        AND U.name IS NULL


                /*ITProduct*/


                        AND CC.category_name LIKE CONCAT('%',#{searchSubSel},'%')
                        AND P.product_name LIKE CONCAT ('%',#{searchTitle},'%')


                        AND CC.category_name IS NULL


                /*Status*/



                            AND ( PD.product_state LIKE CONCAT('%',#{searchSubSel_N},'%') OR PD.product_state
                            LIKE CONCAT('%',#{searchSubSel_R},'%') )


                            AND PD.product_state LIKE CONCAT('%',#{searchSubSel},'%')



                        AND PD.product_state IS NULL




                /*ALL*/
                AND PD.product_state IN ('Y', 'N', 'R')



    /* 일반 유저 */



                AND P.product_name LIKE CONCAT('%',#{searchTitle},'%')


                AND DATE(PD.rental_date) = #{searchSubSel}


                AND DATE(PD.return_date) = #{searchSubSel}



                    AND PD.product_state = #{searchSubSel}


                    AND (PD.product_state = #{searchSubSel_N}
                    OR PD.product_state = #{searchSubSel_R})



                AND PD.product_state IN ('Y', 'N', 'R')




ORDER BY PD.rental_date DESC
LIMIT #{pageIndex}, #{pageSize}

/* Int */
SELECT
    COUNT(*)
FROM tb_product_detail PD
INNER JOIN tb_product_info P ON PD.product_no = P.product_no
INNER JOIN tb_userinfo U ON PD.loginID = U.loginID
INNER JOIN tb_category_code as CC ON PD.category_code = CC.category_code

    /* 괄호를 통해 해당 평가가 먼저 되게 함, () -> NOT-> AND -> OR 순으로 평가됨*/
    (PD.rental_date IS NOT NULL OR PD.return_date IS NOT NULL)

        /* 컨트롤러에서 이 값을 넣으면 일반유저, 없으면 관리자*/
        AND PD.loginID = #{loginID}

    /* 관리자 */





                        AND U.team LIKE CONCAT('%',#{searchSubSel},'%')


                        AND U.team IS NULL




                        AND U.name LIKE CONCAT('%',#{searchSubSel},'%')


                        AND U.name IS NULL




                        AND CC.category_name LIKE CONCAT('%',#{searchSubSel},'%')
                        AND P.product_name LIKE CONCAT ('%',#{searchTitle},'%')


                        AND CC.category_name IS NULL





                            AND ( PD.product_state LIKE CONCAT('%',#{searchSubSel_N},'%') OR PD.product_state
                            LIKE CONCAT('%',#{searchSubSel_R},'%') )


                            AND PD.product_state LIKE CONCAT('%',#{searchSubSel},'%')



                        AND PD.product_state IS NULL




                AND PD.product_state IN ('Y', 'N', 'R')



    /* 일반 유저 */



                AND P.product_name LIKE CONCAT('%',#{searchTitle},'%')


                AND DATE(PD.rental_date) = #{searchSubSel}


                AND DATE(PD.return_date) = #{searchSubSel}



                    AND PD.product_state = #{searchSubSel}


                    AND (PD.product_state = #{searchSubSel_N}
                    OR PD.product_state = #{searchSubSel_R})



                AND PD.product_state IN ('Y', 'N', 'R')

mapper.delete:
/* deleteHistory*/
DELETE
FROM tb_product_detail
WHERE product_no = #{productNo}
  AND product_detail_code = #{productDetailCode}
